<?php
require_once dirname(__DIR__,2).'/app/bootstrap.php';require_admin();$views=(int)db()->query("SELECT COUNT(*) FROM listing_views WHERE viewed_at>=datetime('now','-30 days')")->fetchColumn();$searches=(int)db()->query("SELECT COUNT(*) FROM search_logs WHERE created_at>=datetime('now','-30 days')")->fetchColumn();$visitors=(int)db()->query("SELECT COUNT(DISTINCT visitor_hash) FROM listing_views WHERE viewed_at>=datetime('now','-30 days')")->fetchColumn();$bookings=(int)db()->query("SELECT COUNT(*) FROM bookings WHERE created_at>=datetime('now','-30 days')")->fetchColumn();$quotes=(int)db()->query("SELECT COUNT(*) FROM quote_requests WHERE created_at>=datetime('now','-30 days')")->fetchColumn();$messages=(int)db()->query("SELECT COUNT(*) FROM messages WHERE created_at>=datetime('now','-30 days')")->fetchColumn();$couponSaves=(int)db()->query("SELECT COUNT(*) FROM offer_redemptions WHERE created_at>=datetime('now','-30 days')")->fetchColumn();$top=db()->query("SELECT l.name,l.location,COUNT(v.id) views FROM listing_views v JOIN listings l ON l.id=v.listing_id WHERE v.viewed_at>=datetime('now','-30 days') GROUP BY l.id ORDER BY views DESC LIMIT 12")->fetchAll();$terms=db()->query("SELECT query_text,area_text,COUNT(*) searches,ROUND(AVG(result_count),1) avg_results FROM search_logs WHERE created_at>=datetime('now','-30 days') GROUP BY query_text,area_text ORDER BY searches DESC LIMIT 15")->fetchAll();$adminTitle='Analytics';include __DIR__.'/_header.php';?>
<div class="stats-grid"><article class="stat-card"><span>Listing views · 30 days</span><strong><?= $views ?></strong><small>Deduplicated per visitor for 30 minutes</small></article><article class="stat-card"><span>Unique visitors · 30 days</span><strong><?= $visitors ?></strong><small>Anonymous random visitor token</small></article><article class="stat-card"><span>Searches · 30 days</span><strong><?= $searches ?></strong><small>Queries and areas recorded</small></article><article class="stat-card"><span>Published listings</span><strong><?= (int)db()->query("SELECT COUNT(*) FROM listings WHERE status='published'")->fetchColumn() ?></strong><small>Current public directory</small></article></div><div class="stats-grid stats-grid-secondary"><article class="stat-card"><span>Booking requests · 30 days</span><strong><?= $bookings ?></strong></article><article class="stat-card"><span>Quote requests · 30 days</span><strong><?= $quotes ?></strong></article><article class="stat-card"><span>Business messages · 30 days</span><strong><?= $messages ?></strong></article><article class="stat-card"><span>Offers saved · 30 days</span><strong><?= $couponSaves ?></strong></article></div><div class="admin-panel"><div class="panel-heading"><div><span class="eyebrow">WHAT PEOPLE OPEN</span><h2>Most viewed listings</h2></div></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>Listing</th><th>Area</th><th>Views</th></tr></thead><tbody><?php foreach($top as $r): ?><tr><td><?= h($r['name']) ?></td><td><?= h($r['location']) ?></td><td><strong><?= (int)$r['views'] ?></strong></td></tr><?php endforeach; ?><?php if(!$top): ?><tr><td colspan="3" class="empty-admin">No listing views have been recorded yet.</td></tr><?php endif; ?></tbody></table></div></div><div class="admin-panel"><div class="panel-heading"><div><span class="eyebrow">SEARCH DEMAND</span><h2>Popular searches and gaps</h2></div></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>Search</th><th>Area</th><th>Searches</th><th>Avg. results</th></tr></thead><tbody><?php foreach($terms as $r): ?><tr><td><?= h($r['query_text']?:'—') ?></td><td><?= h($r['area_text']?:'—') ?></td><td><?= (int)$r['searches'] ?></td><td><?= h((string)$r['avg_results']) ?></td></tr><?php endforeach; ?><?php if(!$terms): ?><tr><td colspan="4" class="empty-admin">No search activity yet.</td></tr><?php endif; ?></tbody></table></div><p class="form-footnote">Analytics store a random browser token hash, not raw IP addresses. Use a privacy notice to explain analytics to visitors.</p></div><?php include __DIR__.'/_footer.php';?>
